INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_4a041272a8','社区访客',5,'到访酒仙桥十街坊社区服务站时，周六上午只有值班窗口开放。复杂业务要留到工作日处理。','2026-03-18T14:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_75a28c29ab','周边住户',3,'服务台可暂存小件物品。当天的现场情况是：工作日晚间大部分店铺正常营业。','2026-04-23T15:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_b444975dfb','附近居民',4,'傍晚照明覆盖主路和儿童活动区，而且靠近草坪的小路亮度稍低。','2026-05-02T16:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_3a9825674d','通勤用户',5,'这次经过积水潭地铁站，雨天进站口容易积水；工作人员临时铺设了防滑垫。','2026-06-07T17:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_d30430bf0d','社区访客',3,'夜间到店仍能买到日用品。从入口到服务区域，后门卸货时会短暂占用一段人行道。','2026-01-12T18:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_c73c7711fe','周边住户',4,'复杂业务要留到工作日处理；实际到访时周六上午只有值班窗口开放。','2026-02-17T08:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_c41c366dfb','附近居民',5,'上午到马家堡嘉园南门公交站，晚间末班前客流不多。另外，无障碍电梯入口与普通闸机相隔约五十米。','2026-03-22T09:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_52be01fcec','通勤用户',3,'晚饭前蔬菜和鲜奶补货较全。晚些时候再次经过时，收银高峰排队约十分钟。','2026-04-27T10:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_20bfceda49','社区访客',4,'工作人员能打印受理回执。整体来看，现场公告列出了门禁和搬家登记材料。','2026-05-06T11:00:00+08:00');
INSERT INTO place_reviews(place_id,author,rating,text,time) VALUES ('bjp_6e20703aeb','周边住户',5,'带大件行李从南门进入更方便；另外，一层通道没有明显台阶。','2026-06-11T12:00:00+08:00');
